import{_ as e,o as s,c as t,a5 as i}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Artifact Brief and Delivery Card","description":"Manage a reviewable, handover-ready learning or project artifact with audience, baseline, versions, feedback, quality gates, and rollback.","frontmatter":{"title":"Artifact Brief and Delivery Card","description":"Manage a reviewable, handover-ready learning or project artifact with audience, baseline, versions, feedback, quality gates, and rollback.","updated":"2026-08-31T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/artifact-brief.en.md","name":"artifact-brief.en.md"}},"headers":[],"relativePath":"en/templates/artifact-brief.md","filePath":"en/templates/artifact-brief.md","lastUpdated":1788134400000}'),n={name:"en/templates/artifact-brief.md"};function r(d,a,l,o,p,h){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="artifact-brief-and-delivery-card" tabindex="-1">Artifact Brief and Delivery Card <a class="header-anchor" href="#artifact-brief-and-delivery-card" aria-label="Permalink to &quot;Artifact Brief and Delivery Card&quot;">​</a></h1><p>An artifact does not need to be complete on day one, but it needs boundaries on day one. Copy this card into a private project directory and keep the independent, revised, reviewed, and delivered versions. Do not include passwords, client data, unauthorised third-party information, or unnecessary personal details.</p><h2 id="_1-artifact-boundary" tabindex="-1">1. Artifact boundary <a class="header-anchor" href="#_1-artifact-boundary" aria-label="Permalink to &quot;1. Artifact boundary&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Artifact Brief — YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Artifact name:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Audience/user:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One problem to solve:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inputs and sources:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My current baseline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Key assumptions:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest deliverable:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Format, time, and other constraints:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance criteria:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What this will not include:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First-version deadline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who will give feedback:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence to preserve:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">How to shrink, pause, or roll back:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><h2 id="_2-four-versions" tabindex="-1">2. Four versions <a class="header-anchor" href="#_2-four-versions" aria-label="Permalink to &quot;2. Four versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Completion condition</th><th>What to keep</th></tr></thead><tbody><tr><td>Independent</td><td>Complete the smallest action without an answer key or AI writing it</td><td>Original file, time, bottlenecks</td></tr><tr><td>Structure</td><td>Audience can find the problem, conclusion, and next step</td><td>Structural diff, fact/guess marks</td></tr><tr><td>Review</td><td>A real reader, user, peer, or defined AI reviewer completes a review</td><td>Feedback, error categories, accept/reject reasons</td></tr><tr><td>Delivery</td><td>Another person can begin without your oral explanation</td><td>Version, limits, sources, known issues, handover record</td></tr></tbody></table><h2 id="_3-quality-gates" tabindex="-1">3. Quality gates <a class="header-anchor" href="#_3-quality-gates" aria-label="Permalink to &quot;3. Quality gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Check</th><th>Evidence location</th><th>Owner/date</th></tr></thead><tbody><tr><td>Clear</td><td>Does the audience know the problem and next action?</td><td></td><td></td></tr><tr><td>Accurate</td><td>Do facts, citations, code, and numbers return to a source or test?</td><td></td><td></td></tr><tr><td>Usable</td><td>Can the main action work under real constraints?</td><td></td><td></td></tr><tr><td>Maintainable</td><td>Are version, dependencies, limits, and owner visible?</td><td></td><td></td></tr><tr><td>Responsible</td><td>Are privacy, copyright, permissions, and error consequences handled?</td><td></td><td></td></tr></tbody></table><p>Write “unverified” when there is no evidence for a pass. Speed, word count, and feature count are proxy measures, not quality gates.</p><h2 id="_4-ai-and-feedback-record" tabindex="-1">4. AI and feedback record <a class="header-anchor" href="#_4-ai-and-feedback-record" aria-label="Permalink to &quot;4. AI and feedback record&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI/tool and date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Work it was allowed to do:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Human judgments I kept:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Three highest-impact issues it raised:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I accepted/rejected, and why:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Main point restated by a real reader/user:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Most important repair:</span></span></code></pre></div><p>Save your version first, then use AI to diagnose, simulate an audience, or generate a parallel task. A person confirms critical facts, permissions, privacy, cost, and final authorship.</p><h2 id="_5-delivery-and-rollback" tabindex="-1">5. Delivery and rollback <a class="header-anchor" href="#_5-delivery-and-rollback" aria-label="Permalink to &quot;5. Delivery and rollback&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Delivery audience and permission scope:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Delivery date and version:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Instructions:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Known limits:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Support owner/contact:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cost and retention period:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pause/degrade/rollback trigger:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who must be notified after a problem:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>Delivery is not the end. After 3–7 days, run a parallel test and record whether another person can start independently, what still needs explanation, and the one change for the next version.</p><p>Related chapters: <a href="./../threads/part-3/4-artifacts-and-delivery">Artifacts: Turn Learning into Something Made</a> | <a href="./90-day-cycle">90-Day Cycle Map</a></p>`,16)])])}const E=e(n,[["render",r]]);export{k as __pageData,E as default};
